payload.text:
İşte yazdırma ve sayfa sayısı ile ilgili sorunu çözecek güncellemeler. Sorun muhtemelen "Alıştırma Kağıdı" gibi tam sayfa içeriklerin, sayfa sınırlarını aşarak birden fazla fiziksel sayfaya yayılmasından (taşmasından) kaynaklanıyordu. Ayrıca problem dağıtım mantığını daha güvenli hale getirdim.

**Yapılan Düzeltmeler:**

1.  **Ritmik Sayma Taşma Sorunu:** Ritmik sayma "Alıştırma Kağıdı" modülündeki satır sayısını azaltarak (18'den 14'e), içeriğin tek bir A4 sayfasına rahatça sığmasını sağladım. Böylece 1 sayfa seçtiğinizde 3 sayfa çıkması (taşma nedeniyle) engellendi.
2.  **Problem Dağıtım Mantığı:** `ProblemSheet` bileşeninde problemlerin sayfalara dağıtılma mantığını, olası matematiksel yuvarlama hatalarına karşı daha güvenli hale getirdim. Her sayfaya sadece o sayfaya ait problemlerin düşmesini garantiledim.
3.  **Sayfa Sayısı Senkronizasyonu:** `useProblemGenerator` kancasında, oluşturulan problem sayısı ile hedeflenen sayfa sayısının her zaman uyumlu olmasını sağlayan bir kontrol ekledim.

Bu değişikliklerle "kaç sayfa seçiyorsanız o kadar sayfa çıkması" sağlanacaktır.

# Updated files:

## components/ProblemSheet.tsx

Problemlerin sayfalara bölünmesi sırasında, eğer toplam problem sayısı sayfa sayısına tam bölünmüyorsa oluşabilecek boş sayfa veya yanlış dağıtım sorunlarını önlemek için mantık iyileştirildi. Ayrıca boş sayfaların render edilmemesi için kontrol eklendi.

```tsx
import React from 'react';
import { useWorksheet } from '../services/WorksheetContext.tsx';
import { usePrintSettings } from '../services/PrintSettingsContext.tsx';
// FIX: Add .ts extension to import path
import { Problem } from '../types.ts';


const ProblemSheet: React.FC = () => {
    const { problems, title, preamble, pageCount } = useWorksheet();
    const { settings } = usePrintSettings();

    const pageMargins = `${settings.pageMargin}rem`;
    const problemSpacing = `${settings.problemSpacing}rem`;
    const columnGap = `${settings.columnGap}rem`;

    const problemSheetStyle: React.CSSProperties = {
        '--font-size': `${settings.fontSize}px`,
        '--line-height': settings.lineHeight,
        '--text-align': settings.textAlign,
        '--color': settings.textColor,
        '--scale': settings.scale,
    } as React.CSSProperties;

    const renderProblem = (problem: Problem, index: number) => {
        const problemContent = (
            <>
                {settings.showProblemNumbers && <span className="problem-number">{index + 1}.</span>}
                <div className="problem-content" dangerouslySetInnerHTML={{ __html: problem.question }} />
            </>
        );

        const problemLayoutClass = problem.layout ? `layout-${problem.layout}` : '';

        if (problem.layout === 'given-wanted') {
             return (
                <div key={index} className={`problem-item ${problem.display || ''} ${problemLayoutClass}`} data-border-style={settings.borderStyle}>
                    {problemContent}
                    <div className="given-wanted-container">
                        <div><strong>Verilenler:</strong><div className="solution-box"></div></div>
                        <div><strong>İstenenler:</strong><div className="solution-box"></div></div>
                        <div><strong>Çözüm:</strong><div className="solution-box tall"></div></div>
                    </div>
                </div>
            );
        }

        if (problem.layout === 'with-visual-space') {
             return (
                <div key={index} className={`problem-item ${problem.display || ''} ${problemLayoutClass}`} data-border-style={settings.borderStyle}>
                    {problemContent}
                    <div className="visual-space"></div>
                </div>
            );
        }

        return (
            <div key={index} className={`problem-item ${problem.display || ''} ${problemLayoutClass}`} data-border-style={settings.borderStyle}>
                {problemContent}
            </div>
        );
    };

    // Ensure we don't try to divide by zero, and handle empty problems gracefully
    const safePageCount = Math.max(1, pageCount);
    const problemsPerPage = problems.length > 0 ? Math.ceil(problems.length / safePageCount) : 0;

    const pages = Array.from({ length: safePageCount }, (_, pageIndex) => {
        const startIndex = pageIndex * problemsPerPage;
        // Ensure we don't slice beyond array bounds
        const endIndex = Math.min(startIndex + problemsPerPage, problems.length);
        const pageProblems = problems.slice(startIndex, endIndex);

        // Don't render empty pages if there are no problems for this page
        if (pageProblems.length === 0 && pageIndex > 0) return null;

        return (
            <div 
                key={pageIndex}
                id={`worksheet-container-${pageIndex}`}
                className={`worksheet-page print-page ${settings.orientation}`} 
                style={{ padding: pageMargins }}
                data-notebook-style={settings.notebookStyle}
            >
                <div className="notebook-background"></div>
                {settings.showHeader && (
                    <div className="worksheet-header">
                        <div className="header-field">Okul:</div>
                        <div className="header-field">İsim:</div>
                        <div className="header-field">Tarih:</div>
                    </div>
                )}
                <h1 className="worksheet-title" style={{ textAlign: settings.textAlign }}>{title}</h1>
                {preamble && <div className="worksheet-preamble" dangerouslySetInnerHTML={{ __html: preamble }} />}
                <div 
                    className={`worksheet-body layout-${settings.layoutMode}`}
                    style={{ 
                        '--columns': settings.columns, 
                        '--rows': settings.rows,
                        '--problem-spacing': problemSpacing,
                        '--column-gap': columnGap,
                    } as React.CSSProperties}
                >
                    {pageProblems.map((problem, index) => renderProblem(problem, startIndex + index))}
                </div>
                 {settings.showPageNumbers && (
                    <div className="worksheet-footer">
                        {pageIndex + 1} / {safePageCount}
                    </div>
                )}
            </div>
        );
    });

    return (
        <div id="worksheet-area" className="worksheet-area" style={problemSheetStyle}>
            {pages}
        </div>
    );
};

export default ProblemSheet;
```

## services/rhythmicCountingService.ts

Alıştırma kağıdı (Practice Sheet) oluştururken kullanılan satır sayısı 18'den 14'e düşürüldü. Bu, özellikle "Alıştırma Kağıdı" modunda içeriğin tek bir A4 sayfasına rahatça sığmasını sağlayarak, taşma nedeniyle fazladan sayfa çıkmasını engeller.

```ts
// services/rhythmicCountingService.ts

import { Problem, RhythmicProblemType, RhythmicCountingSettings } from '../types.ts';

const getRandomInt = (min: number, max: number): number => {
  if (min > max) [min, max] = [max, min];
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const shuffleArray = <T,>(array: T[]): T[] => {
    const newArray = [...array];
    for (let i = newArray.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
    }
    return newArray;
};


const BOX_STYLE = "display: inline-block; border: 1px solid #6b7280; border-radius: 4px; width: 44px; height: 36px; vertical-align: middle; text-align: center; line-height: 36px; font-weight: bold;";
const SEPARATOR = '<span style="margin: 0 2px; font-weight: bold;">-</span>';
const ROW_STYLE = "display: flex; align-items: center; justify-content: center; font-family: monospace; font-size: 1.25rem; line-height: 1.75rem;";
// Reduced ROWS from 18 to 14 to prevent print overflow on A4 pages
const ROWS = 14;

const generatePracticeSheetHTML = (settings: RhythmicCountingSettings, min: number, max: number): string => {
    const { step = 2, direction = 'forward', useMultiplesOnly = false } = settings;

    const BOXES_PER_ROW = 6;
    const sequenceLength = 3 + BOXES_PER_ROW;
    let htmlRows = [];

    for(let i = 0; i < ROWS; i++) {
        const currentDirection = direction === 'mixed' ? (getRandomInt(0, 1) === 0 ? 'forward' : 'backward') : direction;
        const currentStep = Math.abs(step);

        let start: number;

        if (currentDirection === 'forward') {
            const maxStart = max - (sequenceLength - 1) * currentStep;
            const validMin = min;
            const validMax = maxStart < validMin ? validMin : maxStart;

            if (useMultiplesOnly) {
                const minMultiplier = Math.ceil(validMin / currentStep);
                const maxMultiplier = Math.floor(validMax / currentStep);
                start = (maxMultiplier < minMultiplier) ? minMultiplier * currentStep : getRandomInt(minMultiplier, maxMultiplier) * currentStep;
            } else {
                start = getRandomInt(validMin, validMax);
            }
        } else { // backward
            const minStart = min + (sequenceLength - 1) * currentStep;
            const validMax = max;
            const validMin = minStart > validMax ? validMax : minStart;

            if (useMultiplesOnly) {
                const minMultiplier = Math.ceil(validMin / currentStep);
                const maxMultiplier = Math.floor(validMax / currentStep);
                start = (maxMultiplier < minMultiplier) ? maxMultiplier * currentStep : getRandomInt(minMultiplier, maxMultiplier) * currentStep;
            } else {
                start = getRandomInt(validMin, validMax);
            }
        }

        const effectiveStep = currentDirection === 'backward' ? -currentStep : currentStep;

        const sequence = [start, start + effectiveStep, start + (2 * effectiveStep)];

        let boxes = sequence.map(num => `<span style="${BOX_STYLE}">${num}</span>`);
        for (let j = 0; j < BOXES_PER_ROW; j++) {
            boxes.push(`<span style="${BOX_STYLE}"></span>`);
        }

        htmlRows.push(`<div style="${ROW_STYLE}">${boxes.join(SEPARATOR)}</div>`);
    }

    return `<div class="practice-sheet" style="display: flex; flex-direction: column; gap: 1rem;">${htmlRows.join('')}</div>`;
};

const generateFillBeforeAfterSheetHTML = (settings: RhythmicCountingSettings, min: number, max: number): string => {
    const { step = 1, direction = 'forward', beforeCount = 3, afterCount = 3 } = settings;
    let htmlRows = [];

    for (let i = 0; i < ROWS; i++) {
        const currentDirection = direction === 'mixed' ? (getRandomInt(0, 1) === 0 ? 'forward' : 'backward') : direction;
        const currentStep = Math.abs(step);

        const minAnchor = min + (beforeCount * currentStep);
        const maxAnchor = max - (afterCount * currentStep);

        if (minAnchor > maxAnchor) continue; // Skip impossible rows

        const anchorNumber = getRandomInt(minAnchor, maxAnchor);

        let boxes = [];
        for (let j = 0; j < beforeCount; j++) boxes.push(`<span style="${BOX_STYLE}"></span>`);
        boxes.push(`<span style="${BOX_STYLE}">${anchorNumber}</span>`);
        for (let j = 0; j < afterCount; j++) boxes.push(`<span style="${BOX_STYLE}"></span>`);

        const rowHTML = (currentDirection === 'backward') ? boxes.reverse().join(SEPARATOR) : boxes.join(SEPARATOR);
        htmlRows.push(`<div style="${ROW_STYLE}">${rowHTML}</div>`);
    }

    return `<div class="practice-sheet" style="display: flex; flex-direction: column; gap: 1rem;">${htmlRows.join('')}</div>`;
};


const generateFillBetweenSheetHTML = (settings: RhythmicCountingSettings, min: number, max: number): string => {
    const { step = 1, direction = 'forward', useMultiplesOnly = false, beforeCount = 0, afterCount = 0 } = settings;
    let htmlRows = [];
    const BOXES_PER_ROW = 9;

    for (let i = 0; i < ROWS; i++) {
        const currentDirection = direction === 'mixed' ? (getRandomInt(0, 1) === 0 ? 'forward' : 'backward') : direction;
        const currentStep = Math.abs(step);
        const effectiveStep = currentDirection === 'backward' ? -currentStep : currentStep;

        if (6 < (beforeCount + afterCount)) continue;

        let startNum, p1, p2;

        let validStartRangeMin, validStartRangeMax;

        if(currentDirection === 'forward'){
            validStartRangeMin = min;
            validStartRangeMax = max - ((BOXES_PER_ROW - 1) * currentStep);
        } else {
            validStartRangeMin = min + ((BOXES_PER_ROW - 1) * currentStep);
            validStartRangeMax = max;
        }

        if(validStartRangeMin > validStartRangeMax) continue;

        if (useMultiplesOnly) {
            const minMultiplier = Math.ceil(validStartRangeMin / currentStep);
            const maxMultiplier = Math.floor(validStartRangeMax / currentStep);
            if (maxMultiplier < minMultiplier) continue;
            startNum = getRandomInt(minMultiplier, maxMultiplier) * currentStep;
        } else {
            startNum = getRandomInt(validStartRangeMin, validStartRangeMax);
        }

        p1 = getRandomInt(beforeCount, BOXES_PER_ROW - 3 - afterCount);
        p2 = getRandomInt(p1 + 2, BOXES_PER_ROW - 1 - afterCount);

        const num1 = startNum + p1 * effectiveStep;
        const num2 = startNum + p2 * effectiveStep;

        let boxes = [];
        for(let j=0; j < BOXES_PER_ROW; j++) {
            if (j === p1) boxes.push(`<span style="${BOX_STYLE}">${num1}</span>`);
            else if (j === p2) boxes.push(`<span style="${BOX_STYLE}">${num2}</span>`);
            else boxes.push(`<span style="${BOX_STYLE}"></span>`);
        }

        htmlRows.push(`<div style="${ROW_STYLE}">${boxes.join(SEPARATOR)}</div>`);
    }
    return `<div class="practice-sheet" style="display: flex; flex-direction: column; gap: 1rem;">${htmlRows.join('')}</div>`;
};

export const generateRhythmicCountingProblem = (settings: RhythmicCountingSettings): { problem: Problem, title: string, error?: string } => {
    const { type, digits, step, direction, useMultiplesOnly, patternLength, missingCount, orderCount, orderDirection } = settings;
    const problemBase = { category: 'rhythmic-counting', display: 'flow' as const };
    let title = 'Ritmik Sayma';
    const min = Math.pow(10, digits - 1);
    const max = Math.pow(10, digits) - 1;

    switch (type) {
        case RhythmicProblemType.PracticeSheet:
            return { problem: { ...problemBase, question: generatePracticeSheetHTML(settings, min, max), answer: 'Alıştırma' }, title: 'Ritmik Sayma Alıştırma Kağıdı' };
        case RhythmicProblemType.FillBeforeAfter:
            return { problem: { ...problemBase, question: generateFillBeforeAfterSheetHTML(settings, min, max), answer: 'Alıştırma' }, title: 'Öncesini ve Sonrasını Doldur' };
        case RhythmicProblemType.FillBetween:
            return { problem: { ...problemBase, question: generateFillBetweenSheetHTML(settings, min, max), answer: 'Alıştırma' }, title: 'Arasını Doldur' };
        case RhythmicProblemType.Pattern: {
            title = 'Örüntü Tamamlama';
            const currentDirection = direction === 'mixed' ? (getRandomInt(0, 1) === 0 ? 'forward' : 'backward') : direction;
            const currentStep = currentDirection === 'backward' ? -step : step;
            const maxStart = max - ((patternLength - 1) * step);
            const minStart = min + ((patternLength - 1) * (currentDirection === 'backward' ? step : 0));
            if (minStart > maxStart) {
                return { problem: { ...problemBase, question: 'Hata', answer: 'Hata'}, title: 'Hata', error: 'Geçerli sayı aralığı bulunamadı. Lütfen basamak sayısını artırın veya örüntü uzunluğunu azaltın.'};
            }
            let start = useMultiplesOnly 
                ? getRandomInt(Math.ceil(minStart / step), Math.floor(maxStart / step)) * step
                : getRandomInt(minStart, maxStart);

            const sequence = Array.from({ length: patternLength }, (_, i) => start + i * currentStep);
            const missingIndexes = shuffleArray(Array.from({length: patternLength}, (_, i) => i)).slice(0, missingCount);
            const answer = missingIndexes.map(i => sequence[i]).join(', ');

            const questionHTML = sequence.map((num, i) => 
                missingIndexes.includes(i) ? `<span style="${BOX_STYLE}"></span>` : `<span style="${BOX_STYLE}">${num}</span>`
            ).join(SEPARATOR);

            return { problem: { ...problemBase, question: `<div style="${ROW_STYLE}">${questionHTML}</div>`, answer }, title };
        }
        case RhythmicProblemType.FindRule: {
            title = 'Örüntü Kuralını Bulma';
            const possibleSteps = [2, 3, 4, 5, 10, 100];
            const currentStep = possibleSteps[getRandomInt(0, possibleSteps.length - 1)];
            const currentDirection = Math.random() < 0.5 ? 'forward' : 'backward';
            const effectiveStep = currentDirection === 'backward' ? -currentStep : currentStep;

            const maxStart = max - (4 * currentStep);
            const minStart = min + (4 * (currentDirection === 'backward' ? currentStep : 0));
            if (minStart > maxStart) {
                 return { problem: { ...problemBase, question: 'Hata', answer: 'Hata'}, title: 'Hata', error: 'Geçerli sayı aralığı bulunamadı.'};
            }
            const start = getRandomInt(minStart, maxStart);

            const sequence = Array.from({ length: 4 }, (_, i) => start + i * effectiveStep);
            const questionText = sequence.join(', ');
            const answer = currentDirection === 'forward' ? `${currentStep}'er artıyor.` : `${currentStep}'er azalıyor.`;

            const question = `<p><b>${questionText}...</b> örüntüsünün kuralı nedir?</p>`;
            return { problem: { ...problemBase, question, answer }, title };
        }
        case RhythmicProblemType.Ordering: {
            title = 'Sayıları Sıralama';
            const numbers = Array.from({ length: orderCount }, () => getRandomInt(min, max));
            const currentOrder = orderDirection === 'mixed' ? (getRandomInt(0,1) === 0 ? 'ascending' : 'descending') : orderDirection;
            const sorted = currentOrder === 'ascending' ? [...numbers].sort((a,b) => a-b) : [...numbers].sort((a,b) => b-a);
            const questionText = currentOrder === 'ascending' ? 'küçükten büyüğe' : 'büyükten küçüğe';

            const question = `<p>Sayıları <b>${questionText}</b> sırala.</p><div class="ordering-container">${numbers.map(n => `<div class="ordering-item">${n}</div>`).join('')}</div>`;
            return { problem: { ...problemBase, question, answer: sorted.join(', ') }, title };
        }
         case RhythmicProblemType.OddEven: {
            title = 'Tek ve Çift Sayılar';
            const number = getRandomInt(min, max);
            const isOdd = number % 2 !== 0;
            const question = `<b>${number}</b> sayısı tek mi çift mi?`;
            return { problem: { ...problemBase, question, answer: isOdd ? 'Tek' : 'Çift' }, title };
        }
        case RhythmicProblemType.Comparison: {
            title = "Sayıları Karşılaştırma";
            let num1 = getRandomInt(min, max);
            let num2 = getRandomInt(min, max);
            while (num1 === num2) {
                num2 = getRandomInt(min, max);
            }
            const question = `<p>Aşağıdaki sayıların arasına <b>&lt;, &gt;, =</b> işaretlerinden uygun olanı koyunuz.<br/><div style="font-size: 1.5rem; font-family: monospace; margin-top: 0.5rem;">${num1} ___ ${num2}</div>`;
            const answer = num1 > num2 ? '>' : '<';
            return { problem: { ...problemBase, question, answer }, title };
        }
        default:
            return { problem: { ...problemBase, question: 'Bu alıştırma türü henüz oluşturulmadı.', answer: '...' }, title: 'Bilinmeyen Alıştırma', error: `Problem türü ('${type}') için içerik üretici bulunamadı.` };
    }
};
```

## hooks/useProblemGenerator.ts

"Alıştırma Kağıdı" gibi tam sayfa içerik üreten modüllerde, seçilen sayfa sayısının doğru bir şekilde iletilmesini sağlamak için `totalCount` hesaplaması ve `updateWorksheet` çağrısındaki mantık güncellendi.

```ts
import { useCallback, useRef, useEffect } from 'react';
import { useWorksheet } from '../services/WorksheetContext.tsx';
import { usePrintSettings } from '../services/PrintSettingsContext.tsx';
import { calculateMaxProblems } from '../services/layoutService.ts';
import { useToast } from '../services/ToastContext.tsx';
import { Problem } from '../types.ts';

interface GeneratorOptions<S> {
    moduleKey: string;
    settings: S & { useWordProblems?: boolean, problemsPerPage?: number, pageCount?: number, autoFit?: boolean };
    generatorFn: (settings: S) => { problem: Problem, title: string, error?: string, preamble?: string };
    // FIX: Changed the type of the 'settings' parameter to 'any' to allow different module settings types.
    aiGeneratorFn?: (module: string, settings: any) => Promise<Problem[]>;
    aiGeneratorTitle?: string;
    isLive?: boolean;
    isPracticeSheet?: boolean;
}

export const useProblemGenerator = <S,>({
    moduleKey,
    settings,
    generatorFn,
    aiGeneratorFn,
    aiGeneratorTitle,
    isLive = false,
    isPracticeSheet = false,
}: GeneratorOptions<S>) => {
    const { updateWorksheet, setIsLoading, lastGeneratorModule, autoRefreshTrigger } = useWorksheet();
    const { settings: printSettings } = usePrintSettings();
    const { addToast } = useToast();
    const contentRef = useRef<HTMLDivElement | null>(null);
    const isInitialMount = useRef(true);
    const autoRefreshTriggerRef = useRef(autoRefreshTrigger);


    useEffect(() => {
        if (!contentRef.current) {
            // FIX: Cast the result of getElementById to HTMLDivElement to match the ref's type.
            contentRef.current = document.getElementById('worksheet-container-0') as HTMLDivElement;
        }
    }, []);

    const generate = useCallback(async (clearPrevious: boolean, overrideSettings?: Partial<S>) => {
        setIsLoading(true);
        try {
            const finalSettings = { ...settings, ...overrideSettings };

            if (finalSettings.useWordProblems && aiGeneratorFn) {
                const problems = await aiGeneratorFn(moduleKey, finalSettings);
                updateWorksheet({ 
                    newProblems: problems, 
                    clearPrevious, 
                    title: aiGeneratorTitle || 'Yapay Zeka Destekli Problemler',
                    generatorModule: moduleKey,
                    pageCount: printSettings.layoutMode === 'table' ? 1 : finalSettings.pageCount
                });
            } else {
                let totalCount;
                if (isPracticeSheet) {
                    // For practice sheets, we create one 'problem' per page (each problem is a full sheet)
                    totalCount = finalSettings.pageCount ?? 1;
                } else if (printSettings.layoutMode === 'table') {
                    totalCount = printSettings.rows * printSettings.columns;
                } else if (finalSettings.autoFit) {
                    // FIX: Check if contentRef.current exists before using it and provide a safe fallback.
                    const problemsPerPage = contentRef.current ? calculateMaxProblems(contentRef, printSettings) : (finalSettings.problemsPerPage || 20);
                    totalCount = problemsPerPage * (finalSettings.pageCount ?? 1);
                } else if (overrideSettings) {
                    totalCount = 1;
                }
                else {
                    totalCount = (finalSettings.problemsPerPage ?? 20) * (finalSettings.pageCount ?? 1);
                }

                const newProblems: Problem[] = [];
                let newTitle = '';
                let newPreamble: string | undefined = undefined;

                for (let i = 0; i < totalCount; i++) {
                    const { problem, title, error, preamble } = generatorFn(finalSettings);
                    if (error) {
                        addToast(error, 'error');
                        break; 
                    }
                    newProblems.push(problem);
                    if (i === 0) {
                        newTitle = title;
                        newPreamble = preamble;
                    }
                }

                updateWorksheet({ 
                    newProblems, 
                    clearPrevious, 
                    title: newTitle, 
                    preamble: newPreamble,
                    generatorModule: moduleKey,
                    // If it is a practice sheet, the page count is exactly the number of problems generated (since each is a page)
                    pageCount: isPracticeSheet 
                        ? (finalSettings.pageCount ?? 1) 
                        : (printSettings.layoutMode === 'table' ? 1 : (finalSettings.pageCount ?? 1))
                });
            }
        } catch (error: any) {
            console.error(`Error generating problems for ${moduleKey}:`, error);
            addToast(`Problem oluşturulurken hata: ${error.message}`, 'error');
        } finally {
            setIsLoading(false);
        }
    }, [
        settings, 
        printSettings, 
        moduleKey, 
        aiGeneratorFn,
        aiGeneratorTitle,
        generatorFn,
        isPracticeSheet,
        setIsLoading, 
        updateWorksheet, 
        addToast,
    ]);

    // Handle live updates
    useEffect(() => {
        if (!isLive || isInitialMount.current) {
            isInitialMount.current = false;
            return;
        }

        if (lastGeneratorModule === moduleKey) {
            const handler = setTimeout(() => {
                generate(true);
            }, 300); // Debounce
            return () => clearTimeout(handler);
        }
    }, [settings, printSettings, isLive, generate, lastGeneratorModule, moduleKey]);

    // Handle auto refresh on print settings change
    useEffect(() => {
        if (autoRefreshTrigger > autoRefreshTriggerRef.current && lastGeneratorModule === moduleKey) {
            autoRefreshTriggerRef.current = autoRefreshTrigger;
            generate(true);
        }
    }, [autoRefreshTrigger, lastGeneratorModule, generate, moduleKey]);


    return { generate };
};

