const createVisualUnitHTML = (num: number, theme: string, selectedEmoji: string): string => {
    let visualContent = '';

    // Use Dice or Domino for 'shapes' or sometimes 'mixed' theme
    const useSpecialVisual = (theme === 'shapes' || (theme === 'mixed' && Math.random() < 0.4));

    if (useSpecialVisual && num <= 6) {
        visualContent = drawDice(num);
    } else if (useSpecialVisual && num <= 12) {
        // For domino, we need 2 numbers that sum to num
        const a = getRandomInt(0, Math.min(6, num));
        const b = num - a;
        if(b <= 6) {
            visualContent = drawDomino(a, b);
        } else {
             // Fallback to emojis if split isn't possible on standard domino
             const MAX_EMOJI_PER_LINE = 5;
             for (let i = 1; i <= num; i++) {
                visualContent += selectedEmoji;
                if (i % MAX_EMOJI_PER_LINE === 0 && i < num) visualContent += '<br>';
            }
        }
    } else {
        const MAX_EMOJI_PER_LINE = 5;
        for (let i = 1; i <= num; i++) {
            visualContent += selectedEmoji;
            if (i % MAX_EMOJI_PER_LINE === 0 && i < num) visualContent += '<br>';
        }
    }

    const boxHtml = `<div style="border: 1.5px solid #9ca3af; border-radius: 6px; height: var(--visual-box-height); width: var(--visual-box-width); margin-top: 0.5rem; background-color: #f9fafb;"></div>`;

