export const drawCalendar = (monthName: string, startDay: number, daysInMonth: number, highlightDay?: number): string => {
    const days = ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'];

    let headerHtml = days.map(d => `<text x="${days.indexOf(d) * 30 + 15}" y="20" text-anchor="middle" font-size="10" font-weight="bold" fill="#4b5563">${d}</text>`).join('');

    let daysHtml = '';
    let currentX = startDay;
    let currentY = 0;

    for (let i = 1; i <= daysInMonth; i++) {
        const x = currentX * 30;
        const y = 40 + currentY * 25;

        const isHighlight = i === highlightDay;
        const highlightCircle = isHighlight ? `<circle cx="${x+15}" cy="${y-4}" r="10" fill="none" stroke="#ef4444" stroke-width="2" />` : '';

        daysHtml += `
            <text x="${x + 15}" y="${y}" text-anchor="middle" font-size="12" fill="${isHighlight ? '#ef4444' : '#1f2937'}" font-weight="${isHighlight ? 'bold' : 'normal'}">${i}</text>
            ${highlightCircle}
        `;

        currentX++;
        if (currentX > 6) {
            currentX = 0;
            currentY++;
        }
    }

    const totalHeight = 50 + (currentY + (currentX === 0 ? 0 : 1)) * 25;

    return `
        <div style="display: inline-block; border: 2px solid #cbd5e1; border-radius: 8px; overflow: hidden; background: white; margin: 0 auto;">
            <div style="background: #3b82f6; color: white; padding: 4px; text-align: center; font-weight: bold; font-family: sans-serif;">${monthName}</div>
            <svg viewBox="0 0 210 ${totalHeight}" style="width: 210px; display: block;">
                ${headerHtml}
                ${daysHtml}
            </svg>
        </div>
    `;
};

export const drawRuler = (length: number, highlight?: number, unit: 'cm' | 'mm' = 'cm', startVal: number = 0): string => {
    const scale = 30; // pixels per unit (cm)
    const totalUnits = length;
    const width = totalUnits * scale + 40;
    const height = 50;

    let marks = '';

    // Draw ticks
    for (let i = 0; i <= totalUnits; i++) {
        const x = 20 + i * scale;
        // Main tick
        marks += `<line x1="${x}" y1="${height}" x2="${x}" y2="${height - 15}" stroke="#374151" stroke-width="1.5" />`;
        // Label
        marks += `<text x="${x}" y="${height - 20}" text-anchor="middle" font-size="10" font-family="monospace" fill="#374151">${startVal + i}</text>`;

        // Millimeter ticks
        if (i < totalUnits) {
            if (unit === 'cm') {
                const midX = x + scale / 2;
                marks += `<line x1="${midX}" y1="${height}" x2="${midX}" y2="${height - 10}" stroke="#9ca3af" stroke-width="1" />`;
            } else {
                for (let j=1; j<10; j++) {
                    const mmX = x + (scale * j / 10);
                    const h = j === 5 ? 10 : 6;
                    marks += `<line x1="${mmX}" y1="${height}" x2="${mmX}" y2="${height - h}" stroke="#9ca3af" stroke-width="0.5" />`;
                }
            }
        }
    }

    let highlightSvg = '';
    if (highlight !== undefined) {
        const x = 20 + (highlight - startVal) * scale;
        highlightSvg = `<path d="M ${x} ${height-25} L ${x-5} ${height-35} H ${x+5} Z" fill="#ef4444" />`;
    }

    return `
        <svg viewBox="0 0 ${width} ${height}" style="max-width: 100%; height: ${height}px; display: block; margin: auto;">
            <rect x="0" y="0" width="${width}" height="${height}" fill="#fef3c7" stroke="#d97706" stroke-width="1" rx="4" />
            ${marks}
            ${highlightSvg}
        </svg>
    `;
};

export const drawThermometer = (value: number): string => {
    // Value range typical -10 to 40
    const min = -10;
    const max = 40;
    const range = max - min;
    const height = 150;
    const width = 60;
    const bulbRadius = 15;
    const stemWidth = 12;
    const scaleY = (height - bulbRadius * 2 - 20) / range; // Pixels per degree

    // Position
    const cx = width / 2;
    const stemTop = 10;
    const zeroY = stemTop + max * scaleY;
    const mercuryY = zeroY - value * scaleY;

    // Ticks
    let ticks = '';
    for (let t = min; t <= max; t += 10) {
        const y = zeroY - t * scaleY;
        ticks += `<line x1="${cx + stemWidth/2}" y1="${y}" x2="${cx + stemWidth/2 + 8}" y2="${y}" stroke="black" stroke-width="1"/>`;
        ticks += `<text x="${cx + stemWidth/2 + 12}" y="${y + 3}" font-size="9" font-family="sans-serif">${t}</text>`;
    }
    for (let t = min; t <= max; t += 5) {
        if (t % 10 !== 0) {
            const y = zeroY - t * scaleY;
            ticks += `<line x1="${cx + stemWidth/2}" y1="${y}" x2="${cx + stemWidth/2 + 5}" y2="${y}" stroke="black" stroke-width="0.5"/>`;
        }
    }

    return `
        <svg viewBox="0 0 ${width} ${height + 10}" style="height: 150px; display: block; margin: auto;">
            <!-- Glass stem -->
            <rect x="${cx - stemWidth/2}" y="${stemTop}" width="${stemWidth}" height="${height - bulbRadius}" rx="${stemWidth/2}" fill="white" stroke="#cbd5e1" stroke-width="1"/>

            <!-- Bulb -->
            <circle cx="${cx}" cy="${height - bulbRadius}" r="${bulbRadius}" fill="white" stroke="#cbd5e1" stroke-width="1"/>

            <!-- Mercury Stem -->
            <rect x="${cx - stemWidth/2 + 2}" y="${mercuryY}" width="${stemWidth - 4}" height="${(height - bulbRadius) - mercuryY}" fill="#ef4444"/>

            <!-- Mercury Bulb -->
            <circle cx="${cx}" cy="${height - bulbRadius}" r="${bulbRadius - 2}" fill="#ef4444"/>

            <!-- Ticks -->
            ${ticks}
        </svg>
    `;
};

export const drawBeaker = (capacity: number, level: number, unit: string = 'mL'): string => {
    const width = 80;
    const height = 120;
    const padding = 10;
    const beakerHeight = height - padding * 2;
    const beakerWidth = width - padding * 2;

    // Simple graduation logic
    const step = capacity / 5;
    let ticks = '';
    const pxPerUnit = beakerHeight / capacity;

    for (let v = step; v <= capacity; v += step) {
        const y = (height - padding) - (v * pxPerUnit);
        ticks += `<line x1="${padding + beakerWidth}" y1="${y}" x2="${padding + beakerWidth - 10}" y2="${y}" stroke="black" stroke-width="1"/>`;
        ticks += `<text x="${padding + beakerWidth - 12}" y="${y+3}" text-anchor="end" font-size="9" font-family="sans-serif">${v}</text>`;
    }

    const fluidHeight = level * pxPerUnit;
    const fluidY = (height - padding) - fluidHeight;

    return `
        <svg viewBox="0 0 ${width} ${height}" style="height: 120px; display: block; margin: auto;">
            <!-- Fluid -->
            <rect x="${padding}" y="${fluidY}" width="${beakerWidth}" height="${fluidHeight}" fill="#bfdbfe" fill-opacity="0.6"/>

            <!-- Beaker Outline -->
            <path d="M ${padding} ${padding} V ${height - padding - 5} Q ${padding} ${height - padding} ${padding + 5} ${height - padding} H ${width - padding - 5} Q ${width - padding} ${height - padding} ${width - padding} ${height - padding - 5} V ${padding}" fill="none" stroke="#475569" stroke-width="2"/>

            <!-- Spout -->
            <path d="M ${width - padding} ${padding} L ${width} ${padding - 5}" stroke="#475569" stroke-width="2"/>

            <!-- Ticks -->
            ${ticks}
            <text x="${width/2}" y="${height - padding - 5}" text-anchor="middle" font-size="10" fill="#475569">${unit}</text>
        </svg>
    `;
};

export const drawBalanceScale = (leftWeight: number, rightWeight: number): string => {
    // Simple logic: if left > right, tilt left down.
    // Angle max 15 degrees.
    const diff = rightWeight - leftWeight; // Positive means right heavy (tilts right down, angle positive)
    const maxDiff = Math.max(leftWeight, rightWeight) || 1; // avoid div by zero
    // Normalize tilt
    let angle = (diff / (maxDiff * 1.5)) * 20; 
    angle = Math.max(-20, Math.min(20, angle)); // Clamp

    const width = 150;
    const height = 100;
    const fulcrumX = 75;
    const fulcrumY = 80;
    const beamLength = 120;

    return `
        <svg viewBox="0 0 ${width} ${height}" style="height: 100px; display: block; margin: auto;">
            <!-- Base -->
            <path d="M ${fulcrumX} ${fulcrumY} L ${fulcrumX - 10} ${height} H ${fulcrumX + 10} Z" fill="#4b5563"/>
            <line x1="${fulcrumX}" y1="${fulcrumY}" x2="${fulcrumX}" y2="${height}" stroke="#4b5563" stroke-width="2"/>

            <!-- Rotating Group -->
            <g transform="rotate(${angle}, ${fulcrumX}, ${fulcrumY})">
                <!-- Beam -->
                <line x1="${fulcrumX - beamLength/2}" y1="${fulcrumY}" x2="${fulcrumX + beamLength/2}" y2="${fulcrumY}" stroke="#1f2937" stroke-width="3" stroke-linecap="round"/>

                <!-- Left Pan Chain -->
                <line x1="${fulcrumX - beamLength/2}" y1="${fulcrumY}" x2="${fulcrumX - beamLength/2}" y2="${fulcrumY + 30}" stroke="#9ca3af"/>
                <!-- Right Pan Chain -->
                <line x1="${fulcrumX + beamLength/2}" y1="${fulcrumY}" x2="${fulcrumX + beamLength/2}" y2="${fulcrumY + 30}" stroke="#9ca3af"/>

                <!-- Pans (keep them horizontal by counter-rotating) -->
                <g transform="translate(${fulcrumX - beamLength/2}, ${fulcrumY + 30}) rotate(${-angle})">
                    <path d="M -15 0 A 15 10 0 0 0 15 0 Z" fill="#d1d5db" stroke="#6b7280"/>
                    ${leftWeight > 0 ? `<rect x="-8" y="-12" width="16" height="12" fill="#ef4444" rx="2"/> <text x="0" y="-4" font-size="8" text-anchor="middle" fill="white">${leftWeight}</text>` : ''}
                </g>

                <g transform="translate(${fulcrumX + beamLength/2}, ${fulcrumY + 30}) rotate(${-angle})">
                    <path d="M -15 0 A 15 10 0 0 0 15 0 Z" fill="#d1d5db" stroke="#6b7280"/>
                    ${rightWeight > 0 ? `<rect x="-8" y="-12" width="16" height="12" fill="#3b82f6" rx="2"/> <text x="0" y="-4" font-size="8" text-anchor="middle" fill="white">${rightWeight}</text>` : ''}
                </g>
            </g>
        </svg>
    `;
};

// services/measurementService.ts

import { Problem, MeasurementProblemType, MeasurementSettings, Difficulty, MeasurementDomain } from '../types.ts';
import { drawRuler, drawThermometer, drawBeaker, drawBalanceScale } from './svgService.ts';

const getRandomInt = (min: number, max: number): number => Math.floor(Math.random() * (max - min + 1)) + min;
const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

// --- Conversion Data ---
const conversions = {
    length: [
        { from: 'km', to: 'm', factor: 1000 },
        { from: 'm', to: 'cm', factor: 100 },
        { from: 'cm', to: 'mm', factor: 10 },
    ],
    weight: [
        { from: 't', to: 'kg', factor: 1000 },
        { from: 'kg', to: 'g', factor: 1000 },
        { from: 'g', to: 'mg', factor: 1000 },
    ],
    capacity: [ // Changed from 'volume' to match domain
        { from: 'L', to: 'mL', factor: 1000 },
    ]
};

// --- Helper Functions ---

const getConversionPair = (domain: MeasurementDomain) => {
    if (domain === MeasurementDomain.Length) return conversions.length[getRandomInt(0, conversions.length.length - 1)];
    if (domain === MeasurementDomain.Weight) return conversions.weight[getRandomInt(0, conversions.weight.length - 1)];
    if (domain === MeasurementDomain.Capacity) return conversions.capacity[getRandomInt(0, conversions.capacity.length - 1)];

    // Mixed
    const all = [...conversions.length, ...conversions.weight, ...conversions.capacity];
    return all[getRandomInt(0, all.length - 1)];
};

const generateConversionProblem = (settings: MeasurementSettings): Problem => {
    const { difficulty, domain } = settings;
    const conversion = getConversionPair(domain === MeasurementDomain.Mixed ? MeasurementDomain.Mixed : domain);
    const { from, to, factor } = conversion;

    let question = '', answer = '';
    const toSmaller = Math.random() < 0.5;

    // Adjust difficulty logic
    const level = difficulty === 'mixed' ? (['easy', 'medium', 'hard'] as const)[getRandomInt(0, 2)] : difficulty;

    if (level === 'easy') {
        // Whole numbers
        if (toSmaller) {
            const val = getRandomInt(1, 10);
            question = `${val} ${from} = ... ${to}`;
            answer = `${val * factor} ${to}`;
        } else {
            const val = getRandomInt(1, 10) * factor;
            question = `${val} ${to} = ... ${from}`;
            answer = `${val / factor} ${from}`;
        }
    } else if (level === 'medium') {
        // Simple decimals (0.5, 1.2)
        if (toSmaller) {
            const val = getRandomInt(1, 20) / 2; // .0 or .5
            question = `${val} ${from} = ... ${to}`;
            answer = `${val * factor} ${to}`;
        } else {
            const val = getRandomInt(1, 20) * (factor / 10);
            question = `${val} ${to} = ... ${from}`;
            answer = `${val / factor} ${from}`;
        }
    } else {
        // Hard: Mixed units (3 km 250 m) or complex decimals
        if (toSmaller && Math.random() < 0.6) {
            const big = getRandomInt(1, 9);
            const small = getRandomInt(1, factor - 1);
            question = `${big} ${from} ${small} ${to} = ... ${to}`;
            answer = `${big * factor + small} ${to}`;
        } else {
            const val = getRandomInt(10, factor * 5);
            question = `${val} ${to} = ... ${from}`;
            answer = `${val / factor} ${from}`; // Might result in 1.234
        }
    }

    return {
        question: `<span style="font-size:1.2em; font-family:monospace">${question}</span>`,
        answer,
        category: 'measurement',
        display: 'inline'
    };
};

const generateReadToolProblem = (settings: MeasurementSettings): Problem => {
    const { domain, difficulty } = settings;

    // If mixed, pick a random domain supported by tools
    let activeDomain = domain;
    if (activeDomain === MeasurementDomain.Mixed) {
        activeDomain = [MeasurementDomain.Length, MeasurementDomain.Weight, MeasurementDomain.Capacity, MeasurementDomain.Temperature][getRandomInt(0, 3)];
    }

    let question = '', answer = '', svg = '';

    switch(activeDomain) {
        case MeasurementDomain.Length:
            const len = difficulty === 'easy' ? getRandomInt(1, 15) : getRandomInt(10, 100) / 10;
            const start = (settings.rulerDetail === 'broken' || difficulty === 'hard') ? getRandomInt(1, 5) : 0;
            const displayLen = len + start;
            svg = drawRuler(Math.ceil(displayLen + 2), displayLen, 'cm', 0);
            // Add an arrow indicating the measurement
            question = `<div style="display:flex; flex-direction:column; align-items:center;">
                ${svg}
                <p>Ok ile gösterilen uzunluk kaç cm'dir?</p>
            </div>`;
            answer = `${displayLen} cm`;

            // Override with specific highlight logic inside SVG service if needed, 
            // but here we are simplifying. Let's use the highlight feature of drawRuler.
            svg = drawRuler(Math.ceil(displayLen + 2), displayLen, 'cm', 0);
            question = `<div>${svg}<p style="text-align:center; margin-top:0.5em">Kırmızı ok hangi değeri gösteriyor?</p></div>`;
            break;

        case MeasurementDomain.Temperature:
            const temp = getRandomInt(-10, 40);
            svg = drawThermometer(temp);
            question = `<div style="display:flex; flex-direction:column; align-items:center; gap:1em">
                ${svg}
                <p>Termometre kaç dereceyi gösteriyor?</p>
            </div>`;
            answer = `${temp} °C`;
            break;

        case MeasurementDomain.Capacity:
            const maxCap = 1000; // mL
            const level = getRandomInt(1, 10) * 100;
            svg = drawBeaker(maxCap, level, 'mL');
            question = `<div style="display:flex; flex-direction:column; align-items:center; gap:1em">
                ${svg}
                <p>Kaptaki sıvı miktarı ne kadardır?</p>
            </div>`;
            answer = `${level} mL`;
            break;

        case MeasurementDomain.Weight:
            // Digital scale reading
            const weight = getRandomInt(50, 5000);
            const unit = weight >= 1000 ? 'kg' : 'g';
            const displayWeight = weight >= 1000 ? (weight/1000).toFixed(2) : weight;

            // Simple SVG for digital scale
            svg = `<svg viewBox="0 0 150 80" style="height:80px; display:block; margin:auto">
                <rect x="25" y="20" width="100" height="50" rx="5" fill="#e5e7eb" stroke="#374151" stroke-width="2"/>
                <rect x="40" y="30" width="70" height="30" fill="#d1fae5" stroke="#059669"/>
                <text x="75" y="52" text-anchor="middle" font-family="monospace" font-size="20" fill="#065f46">${displayWeight} ${unit}</text>
            </svg>`;
            question = `<div style="display:flex; flex-direction:column; align-items:center; gap:1em">
                ${svg}
                <p>Terazi kaç ${unit === 'kg' ? 'kilogramı' : 'gramı'} gösteriyor?</p>
            </div>`;
            answer = `${displayWeight} ${unit}`;
            break;
    }

    return { question, answer, category: 'measurement', display: 'flow' };
};

const generateComparisonProblem = (settings: MeasurementSettings): Problem => {
    // Mainly for weight (balance scale) or capacity
    const { domain } = settings;
    let activeDomain = domain === MeasurementDomain.Mixed ? MeasurementDomain.Weight : domain;

    if (activeDomain === MeasurementDomain.Weight) {
        const w1 = getRandomInt(1, 10);
        const w2 = getRandomInt(1, 10);
        const svg = drawBalanceScale(w1, w2);

        let qText = "Terazinin durumu nasıldır?";
        let ansText = "";

        if (w1 > w2) {
            ansText = "Sol taraf daha ağır.";
        } else if (w2 > w1) {
            ansText = "Sağ taraf daha ağır.";
        } else {
            ansText = "Dengede.";
        }

        // Make it a math problem: how much to add?
        if (w1 !== w2) {
            const diff = Math.abs(w1 - w2);
            const lighterSide = w1 < w2 ? "Sol" : "Sağ";
            qText = `Teraziyi dengelemek için ${lighterSide} kefeye kaç birim eklenmelidir?`;
            ansText = `${diff} birim`;
        }

        return {
            question: `<div style="text-align:center">${svg}<p style="margin-top:10px">${qText}</p></div>`,
            answer: ansText,
            category: 'measurement',
            display: 'flow'
        };
    }

    // Fallback to basic comparison text
    return generateConversionProblem({...settings, type: MeasurementProblemType.Conversion});
};

const generateEstimationProblem = (settings: MeasurementSettings): Problem => {
    const items = [
        { name: "Bir elma", val: "150 g", options: ["150 g", "15 kg", "1500 kg"] },
        { name: "Bir fil", val: "5 ton", options: ["5 kg", "50 kg", "5 ton"] },
        { name: "Bir su bardağı", val: "200 mL", options: ["2 L", "200 mL", "20 mL"] },
        { name: "Oda sıcaklığı", val: "22 °C", options: ["2 °C", "22 °C", "80 °C"] },
        { name: "Kapı yüksekliği", val: "2 m", options: ["2 cm", "2 m", "2 km"] },
    ];

    const item = items[getRandomInt(0, items.length - 1)];
    const shuffledOptions = items[0].options.length ? item.options.sort(() => Math.random() - 0.5) : []; // Simple shuffle

    // Manual shuffle to be safe
    const opts = [...item.options].sort(() => 0.5 - Math.random());

    const question = `
        <div style="text-align:center">
            <p style="font-size:1.1em; margin-bottom:10px"><b>${item.name}</b> yaklaşık ne kadardır?</p>
            <div style="display:flex; justify-content:center; gap:15px">
                ${opts.map(o => `<span style="border:1px solid #ccc; padding:5px 10px; border-radius:15px; font-family:sans-serif">${o}</span>`).join('')}
            </div>
        </div>
    `;

    return {
        question,
        answer: item.val,
        category: 'measurement',
        display: 'flow'
    };
};


export const generateMeasurementProblem = (settings: MeasurementSettings): { problem: Problem, title: string } => {
    const { type, domain } = settings;

    let title = "Ölçme";
    const domainNames = { 
        [MeasurementDomain.Length]: "Uzunluk", 
        [MeasurementDomain.Weight]: "Tartma", 
        [MeasurementDomain.Capacity]: "Sıvı Ölçme", 
        [MeasurementDomain.Temperature]: "Sıcaklık",
        [MeasurementDomain.Mixed]: "Ölçüler Karma"
    };
    title = domainNames[domain] || "Ölçme";

    let result: Problem;

    switch (type) {
        case MeasurementProblemType.ReadTool:
            title += " - Araç Okuma";
            result = generateReadToolProblem(settings);
            break;
        case MeasurementProblemType.Comparison:
            title += " - Karşılaştırma";
            result = generateComparisonProblem(settings);
            break;
        case MeasurementProblemType.Estimation:
            title += " - Tahmin";
            result = generateEstimationProblem(settings);
            break;
        case MeasurementProblemType.Conversion:
        default:
            title += " - Dönüştürme";
            result = generateConversionProblem(settings);
            break;
    }

    return { problem: result, title };
};

import React, { useState, useCallback } from 'react';
import { generateMeasurementProblem } from '../services/measurementService.ts';
import { generateContextualWordProblems } from '../services/geminiService.ts';
import { MeasurementSettings, MeasurementProblemType, MeasurementDomain, Difficulty } from '../types.ts';
import Button from '../components/form/Button.tsx';
import NumberInput from '../components/form/NumberInput.tsx';
import Select from '../components/form/Select.tsx';
import Checkbox from '../components/form/Checkbox.tsx';
import TextInput from '../components/form/TextInput.tsx';
import { ShuffleIcon } from '../components/icons/Icons.tsx';
import { usePrintSettings } from '../services/PrintSettingsContext.tsx';
import SettingsPresetManager from '../components/SettingsPresetManager.tsx';
import { TOPIC_SUGGESTIONS } from '../constants.ts';
import HintButton from '../components/form/HintButton.tsx';
import { useProblemGenerator } from '../hooks/useProblemGenerator.ts';

const MeasurementModule: React.FC = () => {
    const { settings: printSettings } = usePrintSettings();
    const [settings, setSettings] = useState<MeasurementSettings>({
        gradeLevel: 3,
        domain: MeasurementDomain.Length,
        type: MeasurementProblemType.Conversion,
        difficulty: 'medium',
        problemsPerPage: 10,
        pageCount: 1,
        useWordProblems: false,
        autoFit: false,
        topic: '',
        rulerDetail: 'cm',
        scaleType: 'balance',
    });

    const { generate } = useProblemGenerator({
        moduleKey: 'measurement',
        settings,
        generatorFn: generateMeasurementProblem,
        aiGeneratorFn: generateContextualWordProblems,
        aiGeneratorTitle: 'Gerçek Hayat Problemleri - Ölçüler'
    });

    const handleSettingChange = (field: keyof MeasurementSettings, value: any) => {
        setSettings(prev => ({ ...prev, [field]: value }));
    };

    const handleRandomTopic = () => {
        const randomTopic = TOPIC_SUGGESTIONS[Math.floor(Math.random() * TOPIC_SUGGESTIONS.length)];
        handleSettingChange('topic', randomTopic);
    };

    const isTableLayout = printSettings.layoutMode === 'table';

    // Domain Specific Helpers
    const showRulerOptions = settings.domain === MeasurementDomain.Length && settings.type === MeasurementProblemType.ReadTool;
    const showScaleOptions = settings.domain === MeasurementDomain.Weight && settings.type === MeasurementProblemType.ReadTool;

    const handleDomainChange = (domain: MeasurementDomain) => {
        setSettings(prev => ({ 
            ...prev, 
            domain,
            // Reset tool specific types when changing domain if they don't apply
            type: (domain === MeasurementDomain.Temperature && prev.type === MeasurementProblemType.Conversion) ? MeasurementProblemType.ReadTool : prev.type 
        }));
    };

    const getHintText = () => {
        if (settings.useWordProblems) return "AI modu, seçilen ölçü birimiyle ilgili (örn: 'manavda ağırlık', 'terzide uzunluk') hikayeleştirilmiş problemler üretir.";
        if (settings.type === MeasurementProblemType.ReadTool) return "Öğrencilerin cetvel, termometre, terazi veya dereceli kap gibi gerçek ölçüm araçlarını okuma becerilerini geliştirir.";
        if (settings.type === MeasurementProblemType.Estimation) return "Gerçek dünyadaki nesnelerin (bir elma, bir kapı vb.) tahmini ölçüleri üzerine farkındalık yaratır.";
        return "Ölçüler modülü, birim dönüştürmeden araç kullanımına kadar kapsamlı bir matematiksel ölçme deneyimi sunar.";
    };

    const handleGenerate = useCallback((clearPrevious: boolean) => {
        generate(clearPrevious);
    }, [generate]);

    return (
        <div className="space-y-3">
            <div className="flex items-center gap-2">
                <h2 className="text-sm font-semibold">Ölçüler Laboratuvarı</h2>
                <HintButton text={getHintText()} />
            </div>

            {/* Domain Tabs */}
            <div className="flex p-1 space-x-1 bg-stone-100 dark:bg-stone-800 rounded-lg">
                {[
                    { id: MeasurementDomain.Length, label: '📏 Uzunluk' },
                    { id: MeasurementDomain.Weight, label: '⚖️ Tartma' },
                    { id: MeasurementDomain.Capacity, label: '🧪 Sıvı' },
                    { id: MeasurementDomain.Temperature, label: '🌡️ Sıcaklık' },
                    { id: MeasurementDomain.Mixed, label: 'Karma' },
                ].map((d) => (
                    <button
                        key={d.id}
                        onClick={() => handleDomainChange(d.id)}
                        className={`
                            w-full py-1.5 text-xs font-medium leading-5 rounded-md focus:outline-none transition-all
                            ${settings.domain === d.id
                                ? 'bg-white dark:bg-stone-600 text-primary shadow'
                                : 'text-stone-500 hover:text-stone-700 hover:bg-white/[0.12]'
                            }
                        `}
                    >
                        {d.label}
                    </button>
                ))}
            </div>

            <div className="p-1.5 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                <Checkbox
                    label="Gerçek Hayat Problemleri (AI)"
                    id="use-word-problems-measurement"
                    checked={!!settings.useWordProblems}
                    onChange={e => handleSettingChange('useWordProblems', e.target.checked)}
                />
                 {settings.useWordProblems && (
                    <div className="mt-1.5 pl-6">
                         <div className="relative">
                            <TextInput
                                label="Senaryo (Örn: Mutfak, İnşaat)"
                                id="measurement-topic"
                                value={settings.topic || ''}
                                onChange={e => handleSettingChange('topic', e.target.value)}
                                className="pr-10"
                            />
                            <button type="button" onClick={handleRandomTopic} className="absolute right-2.5 bottom-[5px] text-stone-500 hover:text-orange-700" title="Rastgele">
                                <ShuffleIcon className="w-5 h-5" />
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-2 gap-2">
                <Select
                    label="Kazanım / Etkinlik"
                    id="measurement-type"
                    value={settings.type}
                    onChange={e => handleSettingChange('type', e.target.value as MeasurementProblemType)}
                    options={[
                        { value: MeasurementProblemType.ReadTool, label: 'Araç Okuma (Görsel)' },
                        { value: MeasurementProblemType.Conversion, label: 'Birim Dönüştürme' },
                        { value: MeasurementProblemType.Comparison, label: 'Kıyaslama & Denge' },
                        { value: MeasurementProblemType.Estimation, label: 'Tahmin Etme' },
                    ]}
                    containerClassName="col-span-2"
                />

                <Select
                    label="Zorluk Seviyesi"
                    id="measurement-difficulty"
                    value={settings.difficulty}
                    onChange={e => handleSettingChange('difficulty', e.target.value as Difficulty)}
                    options={[
                        { value: 'easy', label: 'Başlangıç (Tam Sayılar)' },
                        { value: 'medium', label: 'Orta (Basit Ondalıklar)' },
                        { value: 'hard', label: 'İleri (Karmaşık Birimler)' },
                    ]}
                />

                {/* Dynamic Options based on Domain/Type */}
                {showRulerOptions && (
                     <Select
                        label="Cetvel Detayı"
                        id="ruler-detail"
                        value={settings.rulerDetail}
                        onChange={e => handleSettingChange('rulerDetail', e.target.value)}
                        options={[
                            { value: 'cm', label: 'Sadece CM' },
                            { value: 'mm', label: 'CM ve MM' },
                            { value: 'broken', label: 'Kırık Cetvel (Sıfırdan Başlamayan)' },
                        ]}
                    />
                )}

                <NumberInput 
                    label="Sayfa Başına Soru" 
                    id="problems-per-page" 
                    min={1} max={20} 
                    value={settings.problemsPerPage} 
                    onChange={e => handleSettingChange('problemsPerPage', parseInt(e.target.value))} 
                    disabled={isTableLayout || settings.autoFit} 
                />
            </div>

             <details className="p-2 bg-stone-50 dark:bg-stone-800/50 border border-stone-200 dark:border-stone-700 rounded-lg" open>
                <summary className="text-xs font-semibold cursor-pointer select-none">Sayfa Düzeni</summary>
                <div className="mt-2 space-y-2">
                    <Checkbox label="Otomatik Sığdır" id="auto-fit-measurement" checked={settings.autoFit} onChange={e => handleSettingChange('autoFit', e.target.checked)} disabled={isTableLayout} />
                    <NumberInput label="Sayfa Sayısı" id="page-count" min={1} max={10} value={settings.pageCount} onChange={e => handleSettingChange('pageCount', parseInt(e.target.value))} disabled={isTableLayout} />
                </div>
            </details>

             <SettingsPresetManager moduleKey="measurement" currentSettings={settings} onLoadSettings={setSettings} />

            <div className="flex flex-wrap gap-2 pt-2">
                <Button onClick={() => handleGenerate(true)} size="sm">Oluştur</Button>
                <Button onClick={() => handleGenerate(false)} variant="secondary" size="sm">Ekle</Button>
            </div>
        </div>
    );
};

